def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    urgent_pressure = 0
    rich_competitors = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) >= 250:
                rich_competitors += 1
            if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 3:
                urgent_pressure += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))

    if not alive_opponents:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    danger = 0.0
    if hp <= 2:
        danger += 1.0
    elif hp <= 4:
        danger += 0.6
    elif hp <= 6:
        danger += 0.3

    if no_water_days >= 2:
        danger += 1.0
    elif no_water_days >= 1:
        danger += 0.5

    demand_units = 1 + len(alive_opponents)
    likely_tight = 1 if supply < demand_units * WATER_REQ else 0

    if hp <= 2 or no_water_days >= 2:
        bid = max(92.0, highest_prev + 2.5, DAILY_SALARY * 1.45)
    elif likely_tight:
        bid = max(78.0 + 18.0 * scarcity, avg_prev + 3.0, highest_prev * 0.96)
    else:
        bid = 28.0 + 18.0 * scarcity + 6.0 * urgent_pressure
        if highest_prev > 0:
            bid = max(bid, min(highest_prev - 8.0, 72.0))

    if day >= 8:
        bid += 6.0 * danger
    else:
        bid += 3.0 * danger

    if rich_competitors >= 2 and scarcity > 0.5:
        bid += 6.0

    if supply >= 23 and hp >= 7 and no_water_days == 0:
        bid *= 0.72
    elif supply >= 21 and hp >= 6 and no_water_days == 0:
        bid *= 0.82

    max_safe = budget
    if day <= 3:
        max_safe = min(max_safe, 95.0)
    elif day <= 6:
        max_safe = min(max_safe, 105.0)
    else:
        max_safe = min(max_safe, 120.0)

    if budget < 140:
        max_safe = min(max_safe, budget * 0.72 + 8.0)

    bid = min(bid, max_safe)
    bid = max(0.0, bid)
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        avg_prev = sum(yesterday_bids) / len(yesterday_bids)
        target_bid = avg_prev * 1.05
    else:
        target_bid = DAILY_SALARY * 0.5

    if my_status['hp'] <= 3:
        return min(my_status['budget'], DAILY_SALARY * 1.1)

    return min(my_status['budget'], max(target_bid, DAILY_SALARY * 0.4))
